const {admin,db,auth,send,fail}=require('./_lib');
module.exports=async(req,res)=>{if(req.method!=='POST')return send(res,405,{ok:false});try{const u=await auth(req);const ref=db().ref('users/'+u.uid);const s=await ref.once('value');if(!s.exists()){const member='ZY-'+u.uid.slice(0,6).toUpperCase();const code='ZY'+u.uid.slice(0,8).toUpperCase();await ref.set({uid:u.uid,email:u.email||'',displayName:(u.email||'Member').split('@')[0],memberId:member,referralCode:code,countryCode:'PK',points:0,pointsLocked:0,earnedPoints:0,referrals:0,plan:'Free',createdAt:admin.database.ServerValue.TIMESTAMP});await db().ref('publicProfiles/'+u.uid).set({uid:u.uid,displayName:(u.email||'Member').split('@')[0],countryCode:'PK',earnedPoints:0});}send(res,200,{ok:true});}catch(e){fail(res,e)}};
